using System;using System.IO;using System.Linq;using System.Reflection;using System.Reflection.Emit;using System.Collections.Generic;
class Inspect {static Type[] Types(Assembly a){try{return a.GetTypes();}catch(ReflectionTypeLoadException e){return e.Types.Where(t=>t!=null).ToArray();}}static void Main(string[] args){if(args.Length!=1){Console.Error.WriteLine("Usage: Inspect.exe <Frosthaven_Data/Managed path>");return;}string d=Path.GetFullPath(args[0]);AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>Assembly.LoadFrom(Path.Combine(d,new AssemblyName(e.Name).Name+".dll"));foreach(string f in new[]{"Snapshot.Libs.Localization.dll","Assembly-CSharp.dll"}){var a=Assembly.LoadFrom(Path.Combine(d,f));foreach(var t in Types(a).Where(t=>t.Name=="LocalizationManager" && t.Namespace!="I2.Loc" && t.Namespace!="Libs.Localization")){Console.WriteLine("TYPE "+t.FullName);foreach(var m in t.GetMethods(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance|BindingFlags.DeclaredOnly)){Console.WriteLine(m);if(m.Name=="TryGetTranslation"||m.Name=="GetTranslation")foreach(var p in m.GetParameters())Console.WriteLine("PARAM "+p.Position+" "+p.Name);}foreach(var field in t.GetFields(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance))Console.WriteLine("FIELD "+field);}}}}
